bool isValidSudoku(vector<vector<char>>& board) {
    bool row[9][10] = {}, col[9][10] = {}, box[9][10] = {};
    for (int i = 0; i < 9; i++) {
        for (int j = 0; j < 9; j++) {
            if (board[i][j] == '.') continue;
            int num = board[i][j] - '0';
            int bi = i / 3 * 3 + j / 3;
            if (row[i][num] || col[j][num] || box[bi][num])
                return false;
            row[i][num] = col[j][num] = box[bi][num] = true;
        }
    }
    return true;
}
// 三组哈希表| box索引=(i/3)*3+(j/3) | 空格跳过
